create temporary table action_context(name text primary key,body jsonb);
grant all on action_context to authenticated,service_role;
create function pg_temp.enqueue(p_request uuid default gen_random_uuid(),p_kind text default 'price_save',p_payload jsonb default '{"entryId":"57000000-0000-4000-8000-000000000034","expectedPriceCents":1000,"priceCents":1200}',p_connection uuid default '57000000-0000-4000-8000-000000000021')
returns jsonb language sql as $$ select public.marketplace_account_action_enqueue('57000000-0000-4000-8000-000000000011',p_connection,p_request,p_kind,p_payload)->'action'; $$;
create function pg_temp.claim() returns jsonb language sql as $$ select public.marketplace_browser_work_claim('57000000-0000-4000-8000-000000000041',1,gen_random_uuid(),true)->'claim'; $$;
create function pg_temp.finish(p_name text,p_state text default 'succeeded',p_result jsonb default '{}') returns boolean language sql as $$
  select public.marketplace_account_action_finish((body->>'actionId')::uuid,(body->>'claimToken')::uuid,(body->>'workerId')::uuid,(body->>'workerEpoch')::bigint,(body->>'runnerId')::uuid,p_state,p_result) from action_context where name=p_name;
$$;
create function pg_temp.begin_write(p_name text) returns boolean language sql as $$
  select public.marketplace_account_action_begin_write((body->>'actionId')::uuid,(body->>'claimToken')::uuid,(body->>'workerId')::uuid,(body->>'workerEpoch')::bigint,(body->>'runnerId')::uuid) from action_context where name=p_name;
$$;
