insert into public.platform_operators(user_id) values('57000000-0000-4000-8000-000000000001');
set local role authenticated;
insert into action_context values('profile_replaced',pg_temp.enqueue(gen_random_uuid(),'profile_details_read','{}','57000000-0000-4000-8000-000000000022'));
reset role;
update public.marketplace_browser_profiles set provider_profile_id='replacement-action-profile-b' where connection_id='57000000-0000-4000-8000-000000000022';
select is((select state from public.marketplace_account_actions where public_id=(select (body->>'id')::uuid from action_context where name='profile_replaced')),'cancelled','Profilwechsel darf angenommene Aufträge nicht einem anderen Browserprofil zuordnen');
select is((select state from public.marketplace_account_actions where public_id=(select (body->>'id')::uuid from action_context where name='old_unknown')),'outcome_unknown','Rechte- und Profilwechsel löschen keinen ungeklärten alten Ausgang');
select throws_ok($$delete from public.marketplace_connections where id='57000000-0000-4000-8000-000000000021'$$,'23503',null,'Ungeklärter Ausgang bleibt bei ausdrücklicher Kontolöschung geschützt');
set local role authenticated;
insert into action_context values('delete_waiting',pg_temp.enqueue(gen_random_uuid(),'profile_details_read','{}','57000000-0000-4000-8000-000000000022'));
reset role;
select throws_ok($$delete from public.marketplace_connections where id='57000000-0000-4000-8000-000000000022'$$,'23503',null,'Noch wartender Auftrag verhindert Kontolöschung bis zum bewussten Abbruch');
set local role authenticated;
select public.marketplace_account_action_cancel('57000000-0000-4000-8000-000000000011','57000000-0000-4000-8000-000000000022',(select (body->>'id')::uuid from action_context where name='delete_waiting'));
reset role;
select lives_ok($$delete from public.marketplace_connections where id='57000000-0000-4000-8000-000000000022'$$,'Abgeschlossene und abgebrochene Belege verhindern keine ausdrückliche Kontolöschung');
select is((select count(*)::integer from public.marketplace_account_actions where connection_id='57000000-0000-4000-8000-000000000022'),0,'Explizite Kontolöschung entfernt nur Belege dieses entfernten Kontos');
select is((select count(*)::integer from public.marketplace_browser_sessions where connection_id='57000000-0000-4000-8000-000000000022'),0,'Geschlossene Sitzungen und zugehörige Belege werden ohne Fremdschlüsselrest entfernt');
set local role authenticated;
select throws_ok($$select pg_temp.enqueue((select (body->>'requestId')::uuid from action_context where name='other_account'),'profile_details_read','{}','57000000-0000-4000-8000-000000000022')$$,'42501',null,'Alte Anfragekennung kann gelöschte Verbindungskennung nicht erneut ausführen');
reset role;
update public.marketplace_worker_runtime set broker_capacity_verified_at=clock_timestamp()-interval '46 seconds' where id=1;
set local role service_role;
select is(public.marketplace_browser_effective_capacity(),0,'Veraltete Kapazitätsmeldungen geben keinen neuen Browserplatz frei');
select is(public.marketplace_browser_capacity_report('57000000-0000-4000-8000-000000000099',1,8),false,'Fremder Worker darf keine Hostkapazität setzen');
select throws_ok($$select public.marketplace_browser_capacity_report('57000000-0000-4000-8000-000000000041',1,9)$$,'22023',null,'Hostgrenze größer als acht ist ungültig');
select * from finish();
rollback;
